        text: "Ogni BIM coordinator ci è passato: esporti un file IFC, lo invii al Common Data Environment, e viene rifiutato per errori strutturali di cui non sapevi l'esistenza. Dopo aver eseguito la validazione su migliaia di file IFC, gli stessi sette errori rappresentano la grande maggioranza delle consegne fallite.",
