        type: "p",
        text: "L'IFC impone un ordine rigoroso: IfcProject → IfcSite → IfcBuilding → IfcBuildingStorey → elementi fisici. Quando quest'ordine viene infranto — un Building direttamente sotto Project senza un Site, elementi posizionati in IfcBuilding invece che in un piano — molti strumenti non riescono a costruire correttamente l'albero.",
