        type: "p",
        text: "Ogni file IFC valido deve contenere esattamente un IfcProject. È il nodo radice dell'intera gerarchia del modello. Alcuni flussi di esportazione che generano sotto-modelli lo omettono. Il risultato è un file che viene analizzato senza errori ma non ha alcuna radice spaziale.",
