        type: "p",
        text: "Gli elementi con Name = \"\" o null non costituiscono una violazione dello schema, ma rompono quasi ogni flusso di lavoro a valle: i commenti BCF non possono farvi riferimento chiaramente, le tabelle di computo metrico mostrano righe vuote, e i report delle interferenze diventano illeggibili.",
