        type: "p",
        text: "BCF esiste perché i problemi sopravvivano una volta usciti dal tuo schermo. Il suo intero valore sta nel viewpoint: una posizione della camera, una selezione e un commento, che insieme fanno sì che il destinatario impieghi dieci secondi a trovare il problema invece di dieci minuti.",
