        text: "La validazione gira in un Web Worker separato e non blocca l'interfaccia — il modello 3D dovrebbe restare interattivo mentre la validazione procede in background. Se il processo di caricamento complessivo sembra lento, verifica se il modello si sta caricando dalla cache OPFS (veloce) oppure viene analizzato da zero (più lento per i file grandi). Al primo caricamento, un file da 200 MB richiede 20–40 secondi per essere analizzato anche in locale. I caricamenti successivi dalla cache richiedono 2–5 secondi.",
