        text: "Dalux è una piattaforma danese di BIM e gestione documentale ampiamente usata in Scandinavia e nel Nord Europa. Il suo elemento distintivo più forte è la visualizzazione IFC mobile-first: le app iOS e Android sono costruite appositamente per l'ispezione in cantiere, con creazione di issue BCF direttamente da telefono o tablet. Per general contractor e subappaltatori che coordinano il lavoro in cantiere, Dalux è lo strumento IFC gratuito più capace disponibile.",
