        type: "p",
        text: "Ogni strumento di questa guida che richiede il caricamento in cloud — Autodesk Viewer, Trimble Connect, Dalux, buildingSMART Validation Service — memorizza il tuo file IFC su un server di terze parti. Per la maggior parte dei progetti di costruzione commerciali questo è un compromesso accettabile. Per infrastrutture governative, strutture della difesa, edifici sanitari o qualsiasi progetto soggetto a vincoli di data sovereignty o GDPR, potrebbe non esserlo. Prima di scegliere uno strumento basato su cloud per progetti sensibili, verifica il Data Processing Agreement (accordo sul trattamento dei dati) del fornitore, le opzioni di residenza dei dati e le politiche di conservazione. L'articolo 28 del GDPR richiede un DPA firmato per ogni responsabile del trattamento che gestisce dati personali, che possono includere nomi dei proprietari degli edifici e coordinate incorporate nei set di proprietà IFC.",
